-- Visitor audit modules, consent ledger, editable collector toggles and admin-safe analytics RPC.
alter table public.analytics_events drop constraint if exists analytics_events_event_name_check;
alter table public.analytics_events add constraint analytics_events_event_name_check check(event_name in('page_view','page_exit','click','scroll_depth','form_start','form_submit','form_validation_error','form_abandon','contact_action','js_error','heartbeat'));
create table if not exists public.website_consent_records(id uuid primary key default gen_random_uuid(),consent_uuid uuid not null unique,visitor_uuid text,consent_state text not null check(consent_state in('granted','necessary','withdrawn')),consent_version text not null default '1',page_path text not null default '/',device_category text not null default 'other' check(device_category in('mobile','tablet','desktop','other')),withdrawn boolean not null default false,created_at timestamptz not null default now(),retention_until timestamptz not null default now()+interval '180 days');
create index if not exists consent_created_idx on public.website_consent_records(created_at desc);create index if not exists consent_visitor_idx on public.website_consent_records(visitor_uuid,created_at desc);
alter table public.website_consent_records enable row level security;revoke all on public.website_consent_records from anon,authenticated;grant insert on public.website_consent_records to anon,authenticated;
create policy "Public insert consent history" on public.website_consent_records for insert to anon,authenticated with check(consent_version='1' and consent_state in('granted','necessary','withdrawn'));
create policy "Super Admin reads consent history" on public.website_consent_records for select to authenticated using(public.resolve_current_role()='super_admin');
create table if not exists public.website_analytics_settings(id int primary key check(id=1),tracking_enabled boolean not null default true,track_clicks boolean not null default true,track_scroll boolean not null default true,track_forms boolean not null default true,live_heartbeat boolean not null default true,updated_at timestamptz not null default now(),updated_by uuid);
insert into public.website_analytics_settings(id) values(1) on conflict(id) do nothing;alter table public.website_analytics_settings enable row level security;revoke all on public.website_analytics_settings from anon,authenticated;grant select on public.website_analytics_settings to anon,authenticated;grant update on public.website_analytics_settings to authenticated;
create policy "Public reads tracker toggles" on public.website_analytics_settings for select to anon,authenticated using(true);
create policy "Super Admin edits tracker toggles" on public.website_analytics_settings for update to authenticated using(public.resolve_current_role()='super_admin') with check(public.resolve_current_role()='super_admin');
drop policy if exists "Karma admins read analytics events" on public.analytics_events;revoke select on public.analytics_events from authenticated;
create or replace function public.read_website_analytics_events(p_since timestamptz default now()-interval '30 days',p_limit int default 10000)
returns table(id uuid,event_name text,page_path text,page_title text,element_id text,element_label text,value numeric,visitor_uuid text,session_uuid text,device_category text,created_at timestamptz,unique_visitors bigint,unique_sessions bigint)
language plpgsql security definer set search_path=public as $$ declare role_name text;begin role_name:=public.resolve_current_role();if role_name not in('admin','super_admin') then raise exception 'Access denied';end if;return query with f as(select a.* from public.analytics_events a where a.created_at>=p_since order by a.created_at desc limit least(greatest(coalesce(p_limit,10000),1),20000)),c as(select count(distinct visitor_uuid) v,count(distinct session_uuid) s from f)select f.id,f.event_name,f.page_path,f.page_title,f.element_id,f.element_label,f.value,case when role_name='super_admin' then f.visitor_uuid else null end,case when role_name='super_admin' then f.session_uuid else null end,f.device_category,f.created_at,c.v,c.s from f cross join c order by f.created_at desc;end $$;
revoke all on function public.read_website_analytics_events(timestamptz,int) from public,anon;grant execute on function public.read_website_analytics_events(timestamptz,int) to authenticated;
create or replace function public.purge_expired_website_consent_records() returns bigint language plpgsql security definer set search_path=public as $$ declare n bigint;begin delete from public.website_consent_records where retention_until<now();get diagnostics n=row_count;return n;end $$;revoke all on function public.purge_expired_website_consent_records() from public,anon,authenticated;
do $$ begin if exists(select 1 from pg_extension where extname='pg_cron') then execute $q$select cron.schedule('karma-consent-ledger-cleanup','40 3 * * *','select public.purge_expired_website_consent_records()')$q$;end if;exception when others then raise notice 'Schedule consent cleanup manually if pg_cron is unavailable.';end $$;
